	var got v1alpha1.Task
	if err := yaml.Unmarshal(out, &got); err != nil {
		t.Fatalf("unmarshal: %v\n%s", err, out)
	}
	if !proto.Equal(want, &got) {
		t.Errorf("yaml round trip changed the task\n%s", out)
	}
}

